// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleRefundRequests) predicate.BundleRefundRequests {
	return predicate.BundleRefundRequests(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleRefundRequests) predicate.BundleRefundRequests {
	return predicate.BundleRefundRequests(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleRefundRequests) predicate.BundleRefundRequests {
	return predicate.BundleRefundRequests(sql.NotPredicates(p))
}
